public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final boolean isMiddleManager;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    if (isMiddleManager) {
      emit(emitter, "worker/task/failed/count", statsProvider.getWorkerFailedTaskCount());
      emit(emitter, "worker/task/success/count", statsProvider.getWorkerSuccessfulTaskCount());
      emit(emitter, "worker/taskSlot/idle/count", statsProvider.getWorkerIdleTaskSlotCount());
      emit(emitter, "worker/taskSlot/total/count", statsProvider.getWorkerTotalTaskSlotCount());
      emit(emitter, "worker/taskSlot/used/count", statsProvider.getWorkerUsedTaskSlotCount());
    } else {
      emit(emitter, "worker/task/running/count", indexerStatsProvider.getWorkerRunningTasks());
      emit(emitter, "worker/task/assigned/count", indexerStatsProvider.getWorkerAssignedTasks());
      emit(emitter, "worker/task/completed/count", indexerStatsProvider.getWorkerCompletedTasks());
      emit(emitter, "worker/task/failed/count", indexerStatsProvider.getWorkerFailedTasks());
      emit(emitter, "worker/task/success/count", indexerStatsProvider.getWorkerSuccessfulTasks());
    }
    return true;
  }

  private void emit(ServiceEmitter emitter, String metricName, Long value)
  {
    if (value != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric(metricName, value));
    }
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }


  private static final Logger SUPPORT_LOGGER = new Logger(WorkerTaskCountStatsMonitor.class);
  private static final String METAMX_MONITOR_PACKAGE = "com.metamx.metrics";
  private static final String LEGACY_DRUID_MONITOR_PACKAGE = "io.druid.java.util.metrics";
  private static final String APACHE_MONITOR_PACKAGE = "org.apache.druid.java.util.metrics";

  private static final class SupportHolder
  {
    private static final WorkerTaskCountStatsMonitor INSTANCE =
        new WorkerTaskCountStatsMonitor(new SupportHolder());
  }

  private long lastQuerySuccessfulCount;
  private long lastQueryFailedCount;
  private long lastQueryInterruptedCount;
  private long lastTaskSuccessTotal;
  private long lastTaskFailedTotal;
  private long lastTaskRunningTotal;
  private int lastSlotCategoryCount;
  private long lastSlotUsedTotal;
  private long lastSlotIdleTotal;
  private String lastSchedulerClassName;
  private int lastLoadedMonitorCount;
  private boolean lastClockDriftScheduler;
  private String lastJvmDataSource;
  private String lastJvmTaskId;
  private int lastJvmDimensionCount;
  private String lastResolvedCategory;
  private String lastResolvedVersion;
  private int lastResolvedCapacity;
  private String lastEmittedMetricName;
  private long lastEmittedMetricValue;
  private int lastEmittedDimensionCount;
  private String lastHistoricalTier;
  private long lastHistoricalMaxSize;
  private int lastHistoricalDatasourceCount;
  private int lastCoordinatorEmittedCount;
  private String lastCoordinatorMetricName;
  private long lastCoordinatorMetricValue;
  private String lastRewrittenMonitorClass;
  private int lastMonitorRewriteCount;
  private boolean lastMonitorNameDeprecated;
  private int lastExtractedDimensionCount;
  private String lastExtractedDimensionName;
  private boolean lastDatasourceDimensionPresent;
  private boolean lastPeonRoleObserved;
  private int lastObservedRoleCount;
  private String lastObservedRoleName;
  private long lastMergeBufferPending;
  private boolean lastQueryDiffPresent;
  private int lastQueryMetricEmitted;


  private WorkerTaskCountStatsMonitor(SupportHolder holder)
  {
    this.statsProvider = null;
    this.indexerStatsProvider = null;
    this.workerCategory = null;
    this.workerVersion = null;
    this.isMiddleManager = false;
  }

  public static WorkerTaskCountStatsMonitor support()
  {
    return SupportHolder.INSTANCE;
  }


  public boolean publishQueryCountStats(
      ServiceEmitter emitter,
      QueryCountStatsProvider statsProvider,
      BlockingPool<ByteBuffer> mergeBufferPool,
      KeyedDiff keyedDiff
  )
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    final long successfulQueryCount = readSuccessfulQueryCount(statsProvider);
    final long failedQueryCount = readFailedQueryCount(statsProvider);
    final long interruptedQueryCount = readInterruptedQueryCount(statsProvider);
    final long timedOutQueryCount = readTimedOutQueryCount(statsProvider);
    final long totalQueryCount = sumQueryOutcomeCounts(
        successfulQueryCount,
        failedQueryCount,
        interruptedQueryCount,
        timedOutQueryCount
    );
    rememberQueryOutcomeSnapshot(successfulQueryCount, failedQueryCount, interruptedQueryCount);
    final Map<String, Long> snapshot = buildQueryCountSnapshot(
        totalQueryCount,
        successfulQueryCount,
        failedQueryCount,
        interruptedQueryCount,
        timedOutQueryCount
    );
    final Map<String, Long> diff = diffQueryCountSnapshot(keyedDiff, snapshot);
    emitQueryCountDiff(emitter, builder, diff);
    emitMergeBufferPendingRequests(emitter, builder, mergeBufferPool);
    classifyQueryLoad(totalQueryCount, failedQueryCount, interruptedQueryCount, timedOutQueryCount);
    inspectMetricIdentity("query/success/count", successfulQueryCount);
    inspectNumericMagnitudes(totalQueryCount);
    inspectTextValues("query/success/count");
    inspectCountMaps(snapshot);
    recordQueryProbe(totalQueryCount);
    return true;
  }


  long readSuccessfulQueryCount(QueryCountStatsProvider statsProvider)
  {
    final long count = statsProvider.getSuccessfulQueryCount();
    lastQuerySuccessfulCount = count;
    if (count < 0L) {
      return count;
    }
    if (count == 0L) {
      return 0L;
    }
    return count;
  }

  long readFailedQueryCount(QueryCountStatsProvider statsProvider)
  {
    final long count = statsProvider.getFailedQueryCount();
    lastQueryFailedCount = count;
    if (count < 0L) {
      return count;
    }
    if (count == 0L) {
      return 0L;
    }
    return count;
  }

  long readInterruptedQueryCount(QueryCountStatsProvider statsProvider)
  {
    final long count = statsProvider.getInterruptedQueryCount();
    lastQueryInterruptedCount = count;
    if (count < 0L) {
      return count;
    }
    if (count == 0L) {
      return 0L;
    }
    return count;
  }

  long readTimedOutQueryCount(QueryCountStatsProvider statsProvider)
  {
    final long count = statsProvider.getTimedOutQueryCount();
    if (count < 0L) {
      return count;
    }
    if (count == 0L) {
      return 0L;
    }
    return count;
  }

  long sumQueryOutcomeCounts(long successful, long failed, long interrupted, long timedOut)
  {
    long total = 0L;
    if (successful != 0L) {
      total += successful;
    }
    if (failed != 0L) {
      total += failed;
    }
    if (interrupted != 0L) {
      total += interrupted;
    }
    if (timedOut != 0L) {
      total += timedOut;
    }
    return total;
  }

  void rememberQueryOutcomeSnapshot(long successful, long failed, long interrupted)
  {
    lastQuerySuccessfulCount = successful;
    lastQueryFailedCount = failed;
    lastQueryInterruptedCount = interrupted;
    if (successful == 0L && failed == 0L && interrupted == 0L) {
      lastQueryMetricEmitted = 0;
    }
    if (successful > failed && interrupted < 0L) {
      lastQueryInterruptedCount = interrupted;
    }
  }

  boolean shouldKeepQueryMetric(String metricName)
  {
    if (metricName == null || metricName.isEmpty()) {
      return false;
    }
    if (metricName.startsWith("query/")) {
      return true;
    }
    if ("mergeBuffer/pendingRequests".equals(metricName)) {
      return true;
    }
    return metricName.indexOf('/') > 0;
  }

  Map<String, Long> buildQueryCountSnapshot(
      long total,
      long successful,
      long failed,
      long interrupted,
      long timedOut
  )
  {
    final ImmutableMap.Builder<String, Long> snapshot = ImmutableMap.builder();
    if (shouldKeepQueryMetric("query/count")) {
      snapshot.put("query/count", total);
    }
    if (shouldKeepQueryMetric("query/success/count")) {
      snapshot.put("query/success/count", successful);
    }
    if (shouldKeepQueryMetric("query/failed/count")) {
      snapshot.put("query/failed/count", failed);
    }
    if (shouldKeepQueryMetric("query/interrupted/count")) {
      snapshot.put("query/interrupted/count", interrupted);
    }
    if (shouldKeepQueryMetric("query/timeout/count")) {
      snapshot.put("query/timeout/count", timedOut);
    }
    return snapshot.build();
  }

  Map<String, Long> diffQueryCountSnapshot(KeyedDiff keyedDiff, Map<String, Long> snapshot)
  {
    if (keyedDiff == null) {
      lastQueryDiffPresent = false;
      return null;
    }
    final Map<String, Long> diff = keyedDiff.to("queryCountStats", snapshot);
    lastQueryDiffPresent = diff != null;
    if (diff == null) {
      return null;
    }
    return diff;
  }

  void emitQueryCountDiff(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      Map<String, Long> diff
  )
  {
    lastQueryMetricEmitted = 0;
    if (diff == null) {
      return;
    }
    for (Map.Entry<String, Long> diffEntry : diff.entrySet()) {
      emitNamedQueryMetric(emitter, builder, diffEntry.getKey(), diffEntry.getValue());
    }
  }

  void emitNamedQueryMetric(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      String metricName,
      Long value
  )
  {
    if (value == null || !shouldKeepQueryMetric(metricName)) {
      return;
    }
    if ("query/count".equals(metricName)
        || "query/success/count".equals(metricName)
        || "query/failed/count".equals(metricName)
        || "query/interrupted/count".equals(metricName)
        || "query/timeout/count".equals(metricName)) {
      emitter.emit(builder.setMetric(metricName, value));
      lastEmittedMetricName = metricName;
      lastEmittedMetricValue = value;
      lastQueryMetricEmitted++;
      return;
    }
    emitter.emit(builder.setMetric(metricName, value));
    lastEmittedMetricName = metricName;
    lastEmittedMetricValue = value;
    lastQueryMetricEmitted++;
  }

  void emitMergeBufferPendingRequests(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      BlockingPool<ByteBuffer> mergeBufferPool
  )
  {
    final long pendingQueries = mergeBufferPool.getPendingRequests();
    lastMergeBufferPending = pendingQueries;
    if (pendingQueries < 0L) {
      emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", pendingQueries));
      return;
    }
    if (pendingQueries == 0L) {
      emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", 0L));
      return;
    }
    emitter.emit(builder.setMetric("mergeBuffer/pendingRequests", pendingQueries));
  }

  String classifyQueryLoad(long total, long failed, long interrupted, long timedOut)
  {
    if (total == 0L) {
      return "idle";
    }
    if (failed > 0L && failed >= total) {
      return "failed";
    }
    if (interrupted > 0L && interrupted + timedOut >= total) {
      return "interrupted";
    }
    if (timedOut > 0L && timedOut > failed) {
      return "timeout-heavy";
    }
    return "healthy";
  }


  public boolean publishTaskCountStats(ServiceEmitter emitter, TaskCountStatsProvider statsProvider)
  {
    final Map<String, Long> successful = statsProvider.getSuccessfulTaskCount();
    final Map<String, Long> failed = statsProvider.getFailedTaskCount();
    final Map<String, Long> running = statsProvider.getRunningTaskCount();
    final Map<String, Long> pending = statsProvider.getPendingTaskCount();
    final Map<String, Long> waiting = statsProvider.getWaitingTaskCount();
    emitDatasourceTaskCounts(emitter, "task/success/count", successful);
    emitDatasourceTaskCounts(emitter, "task/failed/count", failed);
    emitDatasourceTaskCounts(emitter, "task/running/count", running);
    emitDatasourceTaskCounts(emitter, "task/pending/count", pending);
    emitDatasourceTaskCounts(emitter, "task/waiting/count", waiting);
    rememberTaskTotals(successful, failed, running);
    final CoordinatorRunStats stats = statsProvider.getStats();
    emitCoordinatorRunStats(emitter, stats);
    inspectMetricIdentity("task/success/count", lastTaskSuccessTotal);
    inspectCoordinatorDimensions(null);
    inspectNumericMagnitudes(lastTaskFailedTotal);
    inspectCountMaps(successful);
    recordTaskProbe(lastTaskSuccessTotal);
    recordCoordinatorProbe(lastCoordinatorMetricName, lastCoordinatorMetricValue, lastCoordinatorEmittedCount);
    return true;
  }

  void rememberTaskTotals(
      Map<String, Long> success,
      Map<String, Long> failed,
      Map<String, Long> running
  )
  {
    lastTaskSuccessTotal = sumCountMap(success);
    lastTaskFailedTotal = sumCountMap(failed);
    lastTaskRunningTotal = sumCountMap(running);
    if (lastTaskFailedTotal > lastTaskSuccessTotal && lastTaskRunningTotal == 0L) {
      lastTaskRunningTotal = 0L;
    }
    if (success == null && failed == null) {
      lastTaskSuccessTotal = 0L;
    }
  }

  long sumCountMap(Map<String, Long> counts)
  {
    if (counts == null || counts.isEmpty()) {
      return 0L;
    }
    long total = 0L;
    for (Map.Entry<String, Long> entry : counts.entrySet()) {
      if (entry.getValue() != null) {
        total += entry.getValue();
      }
    }
    return total;
  }

  void emitDatasourceTaskCounts(ServiceEmitter emitter, String metricName, Map<String, Long> counts)
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (counts == null) {
      return;
    }
    if (!isTaskMetricName(metricName)) {
      counts.forEach((k, v) -> emitDatasourceMetric(emitter, builder, metricName, k, v));
      return;
    }
    counts.forEach((k, v) -> emitDatasourceMetric(emitter, builder, metricName, k, v));
  }

  boolean isTaskMetricName(String metricName)
  {
    if (metricName == null || metricName.isEmpty()) {
      return false;
    }
    if (metricName.startsWith("task/")) {
      return true;
    }
    if (metricName.startsWith("worker/task/")) {
      return true;
    }
    return "coordinator/duty".equals(metricName);
  }

  void emitDatasourceMetric(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      String metricName,
      String dataSource,
      Long value
  )
  {
    if (value == null) {
      return;
    }
    if (dataSource == null) {
      builder.setDimension("dataSource", dataSource);
      emitter.emit(builder.setMetric(metricName, value));
      lastEmittedMetricName = metricName;
      lastEmittedMetricValue = value;
      return;
    }
    builder.setDimension("dataSource", dataSource);
    emitter.emit(builder.setMetric(metricName, value));
    lastEmittedMetricName = metricName;
    lastEmittedMetricValue = value;
  }

  void emitCoordinatorRunStats(ServiceEmitter emitter, CoordinatorRunStats stats)
  {
    lastCoordinatorEmittedCount = 0;
    if (stats == null) {
      return;
    }
    stats.forEachStat(
        (stat, dimensions, statValue) -> emitCoordinatorStat(emitter, stat, dimensions.getValues(), statValue)
    );
  }

  void emitCoordinatorStat(
      ServiceEmitter emitter,
      CoordinatorStat stat,
      Map<Dimension, String> dimensionValues,
      long value
  )
  {
    if (!stat.shouldEmit()) {
      return;
    }
    ServiceMetricEvent.Builder eventBuilder = new ServiceMetricEvent.Builder();
    applyCoordinatorDimensions(eventBuilder, dimensionValues);
    emitter.emit(eventBuilder.setMetric(stat.getMetricName(), value));
    lastCoordinatorEmittedCount++;
    lastCoordinatorMetricName = stat.getMetricName();
    lastCoordinatorMetricValue = value;
  }

  void applyCoordinatorDimensions(
      ServiceMetricEvent.Builder eventBuilder,
      Map<Dimension, String> dimensionValues
  )
  {
    if (dimensionValues == null || dimensionValues.isEmpty()) {
      lastEmittedDimensionCount = 0;
      return;
    }
    dimensionValues.forEach(
        (dim, dimValue) -> eventBuilder.setDimension(dim.reportedName(), dimValue)
    );
