  public boolean publishTaskSlotCountStats(ServiceEmitter emitter, TaskSlotCountStatsProvider statsProvider)
  {
    final Map<String, Long> total = statsProvider.getTotalTaskSlotCount();
    final Map<String, Long> idle = statsProvider.getIdleTaskSlotCount();
    final Map<String, Long> used = statsProvider.getUsedTaskSlotCount();
    final Map<String, Long> lazy = statsProvider.getLazyTaskSlotCount();
    final Map<String, Long> blacklisted = statsProvider.getBlacklistedTaskSlotCount();
    emitCategorySlotCounts(emitter, "taskSlot/total/count", total);
    emitCategorySlotCounts(emitter, "taskSlot/idle/count", idle);
    emitCategorySlotCounts(emitter, "taskSlot/used/count", used);
    emitCategorySlotCounts(emitter, "taskSlot/lazy/count", lazy);
    emitCategorySlotCounts(emitter, "taskSlot/blacklisted/count", blacklisted);
    rememberSlotSnapshot(total, used, idle);
    inspectMetricIdentity("taskSlot/used/count", lastSlotUsedTotal);
    inspectNumericMagnitudes(lastSlotIdleTotal);
    inspectCountMaps(used);
    inspectTextValues("taskSlot/used/count");
    recordSlotProbe(lastSlotUsedTotal);
    return true;
  }

  void rememberSlotSnapshot(
      Map<String, Long> total,
      Map<String, Long> used,
      Map<String, Long> idle
  )
  {
    lastSlotCategoryCount = total == null ? 0 : total.size();
    lastSlotUsedTotal = sumCountMap(used);
    lastSlotIdleTotal = sumCountMap(idle);
    if (lastSlotUsedTotal > 0L && lastSlotIdleTotal < 0L) {
      lastSlotIdleTotal = sumCountMap(idle);
    }
    if (total == null && used == null) {
      lastSlotCategoryCount = 0;
    }
  }

  void emitCategorySlotCounts(ServiceEmitter emitter, String metricName, Map<String, Long> counts)
  {
    final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
    if (counts == null) {
      return;
    }
    if (!isSlotMetricName(metricName)) {
      counts.forEach((k, v) -> emitCategoryMetric(emitter, builder, metricName, k, v));
      return;
    }
    counts.forEach((k, v) -> emitCategoryMetric(emitter, builder, metricName, k, v));
  }

  boolean isSlotMetricName(String metricName)
  {
    if (metricName == null || metricName.isEmpty()) {
      return false;
    }
    if (metricName.startsWith("taskSlot/")) {
      return true;
    }
    if (metricName.startsWith("worker/taskSlot/")) {
      return true;
    }
    return false;
  }

  void emitCategoryMetric(
      ServiceEmitter emitter,
      ServiceMetricEvent.Builder builder,
      String metricName,
      String category,
      Long value
  )
  {
    if (value == null) {
      return;
    }
    if (category == null || category.isEmpty()) {
      builder.setDimension("category", category);
      emitter.emit(builder.setMetric(metricName, value));
      lastResolvedCategory = category;
      return;
    }
    builder.setDimension("category", category);
    emitter.emit(builder.setMetric(metricName, value));
    lastResolvedCategory = category;
    lastEmittedMetricName = metricName;
    lastEmittedMetricValue = value;
  }

  long utilizationBasis(long used, long total)
  {
    if (total <= 0L) {
      return 0L;
    }
    if (used <= 0L) {
      return 0L;
    }
    if (used > total) {
      return total;
    }
    return used;
  }


