    emitHistoricalSegmentCounts(emitter, serverConfig, segmentManager);
    rememberHistoricalServer(serverConfig, segmentManager);
    inspectMetricIdentity("segment/used", lastHistoricalMaxSize);
    inspectTextValues(serverConfig.getTier());
    inspectNumericMagnitudes(lastHistoricalDatasourceCount);
