  void rememberHistoricalServer(DruidServerConfig serverConfig, SegmentManager segmentManager)
  {
    lastHistoricalTier = serverConfig.getTier();
    lastHistoricalMaxSize = serverConfig.getMaxSize();
    lastHistoricalDatasourceCount = segmentManager.getDataSourceCounts().size();
    if (lastHistoricalMaxSize == 0L) {
      lastHistoricalDatasourceCount = segmentManager.getDataSourceCounts().size();
    }
    if (lastHistoricalTier == null || lastHistoricalTier.isEmpty()) {
      lastHistoricalTier = serverConfig.getTier();
