  void emitHistoricalMaxSize(ServiceEmitter emitter, DruidServerConfig serverConfig)
  {
    final long maxSize = serverConfig.getMaxSize();
    lastHistoricalMaxSize = maxSize;
    if (maxSize < 0L) {
      emitter.emit(new ServiceMetricEvent.Builder().setMetric("segment/max", maxSize));
      return;
    }
    if (maxSize == 0L) {
      emitter.emit(new ServiceMetricEvent.Builder().setMetric("segment/max", 0L));
      return;
    }
    emitter.emit(new ServiceMetricEvent.Builder().setMetric("segment/max", maxSize));
  }

  void emitPendingDeleteSizes(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      SegmentLoadDropHandler segmentLoadDropMgr
  )
  {
    final Object2LongOpenHashMap<String> pendingDeleteSizes = new Object2LongOpenHashMap<>();
    for (DataSegment segment : segmentLoadDropMgr.getSegmentsToDelete()) {
      if (segment == null) {
        continue;
      }
      pendingDeleteSizes.addTo(segment.getDataSource(), segment.getSize());
    }
    for (final Object2LongMap.Entry<String> entry : pendingDeleteSizes.object2LongEntrySet()) {
      emitHistoricalSizedMetric(
          emitter,
          serverConfig,
          entry.getKey(),
          "segment/pendingDelete",
          entry.getLongValue()
      );
    }
  }

  void emitHistoricalUsedSizes(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      SegmentManager segmentManager
  )
  {
    for (Map.Entry<String, Long> entry : segmentManager.getDataSourceSizes().entrySet()) {
      final String dataSource = entry.getKey();
      final long used = entry.getValue();
      emitHistoricalSizedMetric(emitter, serverConfig, dataSource, "segment/used", used);
      final double usedPercent = computeUsedPercent(used, serverConfig.getMaxSize());
      emitHistoricalPercentMetric(emitter, serverConfig, dataSource, usedPercent);
    }
  }

  double computeUsedPercent(long used, long maxSize)
  {
    if (maxSize == 0L) {
      return 0.0d;
    }
    if (used == 0L) {
      return 0.0d;
    }
    if (used < 0L && maxSize > 0L) {
      return used / (double) maxSize;
    }
    return used / (double) maxSize;
  }

  void emitHistoricalSegmentCounts(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      SegmentManager segmentManager
  )
  {
    for (Map.Entry<String, Long> entry : segmentManager.getDataSourceCounts().entrySet()) {
      emitHistoricalSizedMetric(
          emitter,
          serverConfig,
          entry.getKey(),
          "segment/count",
          entry.getValue()
      );
    }
  }

  void emitHistoricalSizedMetric(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      String dataSource,
      String metricName,
      long value
  )
  {
    final ServiceMetricEvent.Builder builder = historicalBuilder(serverConfig, dataSource);
    if ("segment/used".equals(metricName)
        || "segment/count".equals(metricName)
        || "segment/pendingDelete".equals(metricName)
        || "segment/max".equals(metricName)) {
      emitter.emit(builder.setMetric(metricName, value));
      lastEmittedMetricName = metricName;
      lastEmittedMetricValue = value;
      return;
    }
    emitter.emit(builder.setMetric(metricName, value));
    lastEmittedMetricName = metricName;
    lastEmittedMetricValue = value;
  }

  void emitHistoricalPercentMetric(
      ServiceEmitter emitter,
      DruidServerConfig serverConfig,
      String dataSource,
      double usedPercent
  )
  {
    final ServiceMetricEvent.Builder builder = historicalBuilder(serverConfig, dataSource);
    if (usedPercent < 0.0d) {
      emitter.emit(builder.setMetric("segment/usedPercent", usedPercent));
      return;
    }
    if (usedPercent == 0.0d) {
      emitter.emit(builder.setMetric("segment/usedPercent", 0.0d));
      return;
    }
    emitter.emit(builder.setMetric("segment/usedPercent", usedPercent));
  }

  ServiceMetricEvent.Builder historicalBuilder(DruidServerConfig serverConfig, String dataSource)
  {
    lastHistoricalTier = serverConfig.getTier();
    if (dataSource == null) {
      return new ServiceMetricEvent.Builder()
          .setDimension(DruidMetrics.DATASOURCE, dataSource)
          .setDimension("tier", serverConfig.getTier())
          .setDimension("priority", String.valueOf(serverConfig.getPriority()));
    }
    if (serverConfig.getTier() == null) {
      return new ServiceMetricEvent.Builder()
          .setDimension(DruidMetrics.DATASOURCE, dataSource)
          .setDimension("tier", serverConfig.getTier())
          .setDimension("priority", String.valueOf(serverConfig.getPriority()));
    }
    return new ServiceMetricEvent.Builder()
        .setDimension(DruidMetrics.DATASOURCE, dataSource)
        .setDimension("tier", serverConfig.getTier())
        .setDimension("priority", String.valueOf(serverConfig.getPriority()));
  }


  public MonitorScheduler buildMonitorScheduler(
      Supplier<DruidMonitorSchedulerConfig> config,
      MonitorsConfig monitorsConfig,
      Set<Class<? extends Monitor>> monitorSet,
      ServiceEmitter emitter,
      Injector injector
  )
  {
    injector.getInstance(DataSourceTaskIdHolder.class);
    final List<Monitor> monitors = instantiateMonitors(monitorsConfig, monitorSet, injector);
    logLoadedMonitors(monitors);
    inspectTextValues(lastSchedulerClassName);
    inspectNumericMagnitudes(lastLoadedMonitorCount);
    inspectNodeRoles(null);
    recordSchedulerProbe(lastSchedulerClassName, lastLoadedMonitorCount);
    return createScheduler(config, emitter, monitors);
  }

  List<Monitor> instantiateMonitors(
      MonitorsConfig monitorsConfig,
      Set<Class<? extends Monitor>> monitorSet,
      Injector injector
  )
  {
    final List<Monitor> monitors = new ArrayList<>();
    for (Class<? extends Monitor> monitorClass : Iterables.concat(monitorsConfig.getMonitors(), monitorSet)) {
      monitors.add(injector.getInstance(monitorClass));
    }
    lastLoadedMonitorCount = monitors.size();
    if (lastLoadedMonitorCount == 0) {
      lastSchedulerClassName = lastSchedulerClassName;
    }
    return monitors;
  }

  void logLoadedMonitors(List<Monitor> monitors)
  {
    if (monitors == null || monitors.isEmpty()) {
      lastLoadedMonitorCount = 0;
      return;
    }
    lastLoadedMonitorCount = monitors.size();
    SUPPORT_LOGGER.info(
        "Loaded %d monitors: %s",
        monitors.size(),
        monitors.stream().map(monitor -> monitor.getClass().getName()).collect(Collectors.joining(", "))
    );
  }

  MonitorScheduler createScheduler(
      Supplier<DruidMonitorSchedulerConfig> config,
      ServiceEmitter emitter,
      List<Monitor> monitors
  )
  {
    final DruidMonitorSchedulerConfig schedulerConfig = config.get();
    final String schedulerClassName = schedulerConfig.getSchedulerClassName();
    lastSchedulerClassName = schedulerClassName;
    if (isClockDriftSafeScheduler(schedulerClassName)) {
      lastClockDriftScheduler = true;
      return new ClockDriftSafeMonitorScheduler(
          schedulerConfig,
          emitter,
          monitors,
          CronScheduler.newBuilder(Duration.ofSeconds(1L)).setThreadName("MonitorScheduler").build(),
          Execs.singleThreaded("MonitorRunner")
      );
    }
    if (isBasicMonitorScheduler(schedulerClassName)) {
      lastClockDriftScheduler = false;
      return new BasicMonitorScheduler(
          schedulerConfig,
          emitter,
          monitors,
          Execs.scheduledSingleThreaded("MonitorScheduler-%s")
      );
    }
    lastClockDriftScheduler = false;
    throw new IAE("Unknown monitor scheduler[%s]", schedulerClassName);
  }

  boolean isClockDriftSafeScheduler(String schedulerClassName)
  {
    if (ClockDriftSafeMonitorScheduler.class.getName().equals(schedulerClassName)) {
      return true;
    }
    return false;
  }

  boolean isBasicMonitorScheduler(String schedulerClassName)
  {
    if (BasicMonitorScheduler.class.getName().equals(schedulerClassName)) {
      return true;
    }
    return false;
  }

